cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Check user columns and find nina
const cols = db.prepare('PRAGMA table_info(users)').all();
console.log('User columns:', cols.map(c => c.name));

const users = db.prepare(\"SELECT * FROM users WHERE email LIKE '%nina%' OR name LIKE '%nina%' OR LOWER(email) LIKE '%nina%'\").all();
console.log('Nina users:', JSON.stringify(users, null, 2));
"

